请对以下 case 进行三维加权评分。

=== case_id ===
Case-21-stocks-009

=== 用户原始指令 (query.txt) ===
弄个盈亏卡片，数字会变，点一下能卖出，亏太多就红色提示

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "弄个盈亏卡片，数字会变，点一下能卖出，亏太多就红色提示",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "stockapp://trade/sell"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "position": {
        "pnlText": {
          "type": "string",
          "description": "当前持仓盈亏金额展示文本，包含正负号或货币符号。",
          "sampleValue": "¥-860"
        },
        "pnlRatioText": {
          "type": "string",
          "description": "当前持仓盈亏比例展示文本。",
          "sampleValue": "-4.8%"
        },
        "alertText": {
          "type": "string",
          "description": "亏损超过阈值时展示的风险提示短文案。",
          "sampleValue": "亏损过大"
        },
        "alertColor": {
          "type": "string",
          "description": "风险提示文字颜色，亏损过多时为红色系状态色。",
          "sampleValue": "#ffed6f21"
        },
        "actionEnabled": {
          "type": "boolean",
          "description": "卖出动作是否可点击。",
          "sampleValue": true
        }
      }
    }
  },
  "assetCandidates": []
}

